        if is_prime(n) {
            prime_count += 1
        }
    }
    print(prime_count)
}
fn get_primes(n: Int) -> Vec<Int> {
    let mut primes = vec()
    for i in range(2, n + 1) {
        if n % i == 0 && is_prime(i) {
            primes = push(primes, i)
        }
    }
    primes
}
fn is_prime(n: Int) -> Bool {
    if n <= 1 { return false }
    for i in range(2, n) {
        if n % i == 0 { return false }
    }
    true
}

