fn shift_letters(s: Str, n: Int) -> Str {
    let chars = chars(s)
    let shifted_chars = map(chars, |c| {
        let code = unwrap_or(unwrap_or(get(c, 0), -1), -1)
        if code >= 'a' as Int && code <= 'z' as Int {
            let new_code = (code + n - 'a' as Int) % 26 + 'a' as Int
            Some(new_code as Char)
        } else {
            None
        }
    })
    concat(shifted_chars)
}

